static PFNGLCREATESHADERPROC pCreateShader;static PFNGLSHADERSOURCEPROC pShaderSource;static PFNGLCOMPILESHADERPROC pCompileShader;static PFNGLGETSHADERIVPROC pGetShaderiv;static PFNGLCREATEPROGRAMPROC pCreateProgram;static PFNGLATTACHSHADERPROC pAttachShader;static PFNGLBINDATTRIBLOCATIONPROC pBindAttribLocation;static PFNGLLINKPROGRAMPROC pLinkProgram;static PFNGLUSEPROGRAMPROC pUseProgram;static PFNGLGENBUFFERSPROC pGenBuffers;static PFNGLBINDBUFFERPROC pBindBuffer;static PFNGLBUFFERDATAPROC pBufferData;static PFNGLENABLEVERTEXATTRIBARRAYPROC pEnableVertexAttribArray;static PFNGLVERTEXATTRIBPOINTERPROC pVertexAttribPointer;
static PROC gp(const char*n){PROC p=wglGetProcAddress(n);if(!p||p==(PROC)1||p==(PROC)2||p==(PROC)3||p==(PROC)-1)p=GetProcAddress(GetModuleHandleA("opengl32.dll"),n);return p;}
static bool loadGL(){pCreateShader=(PFNGLCREATESHADERPROC)gp("glCreateShader");pShaderSource=(PFNGLSHADERSOURCEPROC)gp("glShaderSource");pCompileShader=(PFNGLCOMPILESHADERPROC)gp("glCompileShader");pGetShaderiv=(PFNGLGETSHADERIVPROC)gp("glGetShaderiv");pCreateProgram=(PFNGLCREATEPROGRAMPROC)gp("glCreateProgram");pAttachShader=(PFNGLATTACHSHADERPROC)gp("glAttachShader");pBindAttribLocation=(PFNGLBINDATTRIBLOCATIONPROC)gp("glBindAttribLocation");pLinkProgram=(PFNGLLINKPROGRAMPROC)gp("glLinkProgram");pUseProgram=(PFNGLUSEPROGRAMPROC)gp("glUseProgram");pGenBuffers=(PFNGLGENBUFFERSPROC)gp("glGenBuffers");pBindBuffer=(PFNGLBINDBUFFERPROC)gp("glBindBuffer");pBufferData=(PFNGLBUFFERDATAPROC)gp("glBufferData");pEnableVertexAttribArray=(PFNGLENABLEVERTEXATTRIBARRAYPROC)gp("glEnableVertexAttribArray");pVertexAttribPointer=(PFNGLVERTEXATTRIBPOINTERPROC)gp("glVertexAttribPointer");return pCreateShader&&pShaderSource&&pCompileShader&&pGetShaderiv&&pCreateProgram&&pAttachShader&&pBindAttribLocation&&pLinkProgram&&pUseProgram&&pGenBuffers&&pBindBuffer&&pBufferData&&pEnableVertexAttribArray&&pVertexAttribPointer;}
