static GLuint compileGL(GLenum t,const char*s){GLuint x=pCreateShader(t);pShaderSource(x,1,&s,nullptr);pCompileShader(x);GLint ok=0;pGetShaderiv(x,GL_COMPILE_STATUS,&ok);return ok?x:0;}
static bool loadGLVerts(const wchar_t*p,std::vector<float>&v){int n=WideCharToMultiByte(CP_UTF8,0,p,-1,nullptr,0,nullptr,nullptr);if(n<=1)return false;std::string path(n-1,'\\0');WideCharToMultiByte(CP_UTF8,0,p,-1,path.data(),n,nullptr,nullptr);cgltf_options o{};cgltf_data*d=nullptr;if(cgltf_parse_file(&o,path.c_str(),&d)!=cgltf_result_success)return false;bool ok=false;for(size_t m=0;m<d->meshes_count&&!ok;m++)for(size_t j=0;j<d->meshes[m].primitives_count&&!ok;j++)for(size_t a=0;a<d->meshes[m].primitives[j].attributes_count;a++)if(d->meshes[m].primitives[j].attributes[a].type==cgltf_attribute_type_position){auto*q=d->meshes[m].primitives[j].attributes[a].data;v.resize(q->count*3);for(size_t i=0;i<q->count;i++)cgltf_accessor_read_float(q,i,&v[i*3],3);ok=true;break;}cgltf_free(d);return ok;}
